5	namespace App\Modules\Events\Policies;
6	
7	use App\Models\Team;
8	use App\Models\User;
9	use Platform\Authz\Core\Contracts\PermissionSubjectInterface;
10	use Platform\Authz\Core\Enums\PermissionAction;
11	use Platform\Authz\Core\Enums\PermissionScope;
12	use Platform\Authz\Policies\ResourcePolicy;
13	
14	/**
15	 * Story 2-1 — Event authorization policy.
16	 *
17	 * Extends ResourcePolicy so all scope resolution (including the SYSTEM_ADMIN
18	 * global bypass) flows through EffectiveScopeResolver rather than a hand-rolled
19	 * isSystemAdmin() role short-circuit (Rule 30).
20	 *
21	 * Capability strings:
22	 *   viewAny → events.view.{team,global}
23	 *   view    → events.view.{team,global}
24	 *   create  → overridden — @can('create', [Event::class, $team]) supplies Team
25	 *   update  → events.update.{team,global}
26	 */
27	class EventPolicy extends ResourcePolicy
28	{
29	    protected string $resourceName = 'events';
30	
31	    /**
32	     * viewAny intentionally resolves `events.view.*` (not a separate `events.viewany.*`
33	     * capability) so any role that can view an event can also list — keeps
34	     * route(events.view.*) and policy in parity.
35	     */
36	    public function viewAny(PermissionSubjectInterface $user): bool
37	    {
38	        $scope = $this->scopeResolver->getEffectiveScope(
39	            $user,
40	            $this->resourceName,
41	            PermissionAction::VIEW->value,
42	        );
43	
44	        return \in_array($scope, [PermissionScope::OWN->value, PermissionScope::TEAM->value, PermissionScope::GLOBAL->value], true);
45	    }
46	
47	    /**
48	     * Story 2-1 — Admin + Co-host may create events.
49	     *
50	     * Overrides ResourcePolicy::create() to handle the Team argument that
51	     * Laravel passes via @can('create', [Event::class, $team]).
52	     *
53	     * When $team is supplied, the check is team-scoped against that team.
54	     * When $team is absent (e.g. base-class callers), falls through to the
55	     * scope resolver's current-team resolution — matching base behaviour.
56	     *
57	     * $team is nullable with a default to satisfy PHP LSP: the parent
58	     * declares create(User): bool with no second param, so any override
59	     * must keep it optional.
60	     */
61	    public function create(PermissionSubjectInterface $user, ?Team $team = null): bool
62	    {
63	        if ($team !== null) {
64	            /** @var User $user */
65	            return $user->hasTeamPermission($team, 'events.create.team');
66	        }
67	
68	        // Fallback: no team supplied — resolve via EffectiveScopeResolver
69	        // (honours events.create.global for SYSTEM_ADMIN cross-team tooling).
70	        $scope = $this->scopeResolver->getEffectiveScope(
71	            $user,
72	            $this->resourceName,
73	            PermissionAction::CREATE->value,
74	        );
75	
76	        return in_array($scope, [PermissionScope::TEAM->value, PermissionScope::GLOBAL->value], true);
77	    }
78	}
