18	/**
19	 * Story 2-1 ATDD — Create Event flow.
20	 *
21	 * Covers AC1 (DRAFT creation + audit), AC2 (capability gate),
22	 * AC3 (validation), AC4 (workspace scoping).
23	 */
24	#[Group('events')]
25	#[Group('p0')]
26	class CreateEventTest extends FeatureTestCase
27	{
28	    protected function setUp(): void
29	    {
30	        parent::setUp();
31	
32	        // Per-process cache from PermissionCacheService can leak between tests
33	        // when RefreshDatabase recycles user IDs (a Co-host in test N becomes a
34	        // Billing Admin in test N+1 with the same user_id, but the cache still
35	        // says they have events.create.team). Wipe the cache between tests.
36	        \Illuminate\Support\Facades\Cache::flush();
37	    }
38	
39	    /**
40	     * Spin up an authenticated admin attached to a team.
41	     *
42	     * @return array{0: User, 1: Team}
43	     */
44	    private function adminWithTeam(): array
45	    {
46	        $user = User::factory()->create();
47	        $team = Team::factory()->create(['user_id' => $user->id]);
48	        $user->teams()->attach($team, ['role' => UserRole::ADMIN->value]);
49	        $user->forceFill(['current_team_id' => $team->id])->save();
50	
51	        return [$user->fresh(), $team->fresh()];
52	    }
53	
54	    private function cohostWithTeam(): array
55	    {
56	        [$owner, $team] = $this->adminWithTeam();
57	        $cohost = User::factory()->create();
58	        $cohost->teams()->attach($team, ['role' => UserRole::CO_HOST->value]);
59	        $cohost->forceFill(['current_team_id' => $team->id])->save();
60	
61	        return [$cohost->fresh(), $team->fresh()];
62	    }
63	
64	    private function billingAdminWithTeam(): array
65	    {
66	        [$owner, $team] = $this->adminWithTeam();
67	        $billing = User::factory()->create();
68	        $billing->teams()->attach($team, ['role' => UserRole::BILLING_ADMIN->value]);
69	        $billing->forceFill(['current_team_id' => $team->id])->save();
70	
71	        return [$billing->fresh(), $team->fresh()];
72	    }
73	
74	    private function validPayload(): array
75	    {
76	        return [
77	            'title' => 'Quarterly Investor Webinar',
78	            'description' => 'Q2 2026 investor update.',
79	            'type' => 'webinar',
80	            'starts_at' => now()->addDays(14)->setTime(14, 0)->toIso8601String(),
81	            'ends_at' => now()->addDays(14)->setTime(15, 0)->toIso8601String(),
82	            'timezone' => 'Europe/Istanbul',
83	        ];
84	    }
