    public function teams()
    {
        return $this->belongsToMany(Team::class, 'team_user')
            ->withPivot('role')
            ->withTimestamps();
    }

    /**
     * Get the roles that belong to the user through team memberships.
     */
    public function roles()
    {
        return $this->belongsToMany(Role::class, 'team_user', 'user_id', 'role', 'id', 'key')
            ->withPivot(['team_id']);
    }

    /**
     * Check if the user has a specific permission for a team
     *
     * @param  Team|null  $team  The team to check permissions for
     * @param  string  $permission  The permission to check
     */
    public function hasTeamPermission($team, $permission): bool
    {
        if (! $team) {
            return false;
        }
        // Delegate to orchestrator for permission check FOR THE SPECIFIC TEAM
        $orchestrator = resolve(PermissionOrchestrator::class);

        return $orchestrator->hasAnyTeamPermissions($this, [$permission], $team->id);
    }

