/**
 * E-PKG S5 — the team must bind a credit at event creation (it has an active
 * paid subscription or a consumable one-off source) but every source is
 * exhausted: the monthly Growth allowance is spent and there is no unconsumed
 * Growth +1 Event add-on and no active, unexpired Launch Pass.
 *
 * Thrown INSIDE the event-creation transaction, so the event row is rolled
 * back — no event is created on an exhausted credit. Maps to HTTP 402.
 */
class EventCreditExhaustedException extends RuntimeException
{
    public static function make(): self
    {
        return new self(__('billing.errors.'.BillingErrorCode::EVENT_CREDIT_EXHAUSTED), 0);
    }

    public function errorCode(): string
    {
        return BillingErrorCode::EVENT_CREDIT_EXHAUSTED;
    }

    public function httpStatus(): int
    {
        return 402;
    }
}

